INSERT INTO `tournament_match_summaries` (`id`,`event_id`,`round`,`best_of`,`leader_one_code`,`archetype_one`,`player_one_name`,`leader_two_code`,`archetype_two`,`player_two_name`,`score_one`,`score_two`,`winner_leader_code`,`winner_side`,`summary`,`source_name`,`source_url`,`evidence_status`) VALUES
('dallas-2026-top32-pudding-luffy-ace','dallas-na-finals-2026','Top 32',3,'OP08-058','Purple/Yellow Charlotte Pudding','KZ','ST30-001','Red/Green Luffy & Ace',NULL,2,0,'OP08-058',1,'KZ wins 2–0 with Purple/Yellow Pudding despite the matchup simulation favoring Luffy & Ace. Game 1: Luffy & Ace opens with Bonney, Thousand Sunny, Nami, and Luffys, but misses the OP12 Luffy into Sanji chain and hard-casts rush Luffys. Pudding uses an event searcher into 3-cost Pudding to draw three, ramps with Yamato and the leader, and withholds attacks on Luffy & Ace’s leader to deny extra life cards and event counters. The 2-cost Katakuri into 6-cost Katakuri and Sweet 3 Generals line stacks −3000 effects, removes key Luffy bodies, and heals. A 10-cost Big Mom and multiple 8k attackers force Luffy & Ace to spend large amounts of hand to preserve a Luffy. Luffy & Ace attempts a Kong Gatling lethal push, but Pudding counters a 13k attack and wins on the next turn. Game 2: Luffy & Ace finds the OP12 Luffy combo late and uses it once after Pudding has established her engine. Pudding repeats the draw, ramp, Katakuri, and Big Mom plan, healing from zero back to two life while building a board of 8k threats. Luffy & Ace applies rush pressure and presents another Kong Gatling turn, but holds a Go All Out that could have locked two Pudding attackers. Pudding counters through the lethal attempt at zero life and closes with Big Mom and multiple 8k swings.','CardKaizoku video analysis summary','https://moochoo.com/leader-guide-op08-058/','VERIFIED'),
('utrecht-2026-semi-robin-black-luffy','utrecht-eu-finals-2026','Semifinal',3,'OP09-062','Purple/Yellow Nico Robin',NULL,'OP17-079','Black Elbaf Monkey.D.Luffy',NULL,2,1,'OP09-062',1,'Nico Robin wins 2–1 and advances to the EU Finals. Game 1: Black Luffy goes second and curves Usopp into Saul and Loki with Elbaf two-drops, pressuring life and building 12-cost blockers. Robin ramps with Brûlée, Yamato, and leader triggers into 10-cost Big Mom, but has no DON left for Gung-Gum Giant. Luffy takes the window before Robin can defend and wins with large attacks. Game 2: Robin stabilizes with Strusen, Brûlée, and trigger bodies, reaches 10 DON for Big Mom, then chains Perospero, Sweet 3 Generals, and Oven into repeated 8k threats and life gain. Luffy stumbles after a Gerd discard with no valid Ground Death target and mismanages pressure into the board. Robin survives the race with Gung-Gum Giant and counter, then wins on the backswing. Game 3: Luffy goes second, develops Usopp, Saul, double Loki, Gerd, and Rodo into a blocker wall and threatens lethal with repeated 8k attacks. Robin repeatedly heals with Big Mom, Sweet 3 Generals, and Perospero, converting triggers into attackers. Luffy attacks life instead of clearing Robin’s board and uses Loki to attack rather than block, giving Robin time to resolve a second Big Mom. Robin counters Luffy’s final attacks with a large hand and Gung-Gum Giant, then closes with Big Mom and 8k attackers.','CardKaizoku video analysis summary','https://www.youtube.com/watch?v=FMYbnHeNYbs','VERIFIED');
